namespace RemoteFrame.Rendering;
internal static class BitmapFont
{
    // 8x12 monochrome glyphs for printable ASCII (first glyph is space).
    private static readonly byte[] Data = Convert.FromBase64String(
        ""
    );
    public static byte Row(char c, int y) => c is >= ' ' and <= '~' ? Data[(c - 32) * 12 + y] : Data[('?' - 32) * 12 + y];
}
